pub fn conversion_plan_element_eq(
    a: Option<Rc<DeclarationRef>>,
    b: Option<Rc<DeclarationRef>>,
) -> bool {
    match a.clone() {
        Some(ae) => match b.clone() {
            Some(be) => crate::std_decl_ref::declaration_ref_eq(ae.clone(), be.clone()),
            std::option::Option::None => false,
        },
        std::option::Option::None => match b.clone() {
            Some(_) => false,
            std::option::Option::None => true,
        },
    }
}

pub fn conversion_endpoint_eq(a: Rc<ConversionEndpoint>, b: Rc<ConversionEndpoint>) -> bool {
    match (*a.clone()).clone() {
        ConversionEndpoint::KernelMintedCarrier {
            minted_name: an, ..
        } => match (*b.clone()).clone() {
            ConversionEndpoint::KernelMintedCarrier {
                minted_name: bn, ..
            } => (an.clone() == bn.clone()),
            ConversionEndpoint::DeclaredCarrier { .. } => false,
        },
        ConversionEndpoint::DeclaredCarrier {
            declaration: ad,
            element: ae,
            ..
        } => match (*b.clone()).clone() {
            ConversionEndpoint::KernelMintedCarrier { minted_name: _, .. } => false,
            ConversionEndpoint::DeclaredCarrier {
                declaration: bd,
                element: be,
                ..
            } => {
                (crate::std_decl_ref::declaration_ref_eq(ad.clone(), bd.clone())
                    && conversion_plan_element_eq(ae.clone(), be.clone()))
            }
        },
    }
}

pub fn judge_conversion_plan(
    rows: Rc<Vec<Rc<ConversionPlan>>>,
    route: Rc<DeclarationRef>,
    source: Rc<ConversionEndpoint>,
    target: Rc<ConversionEndpoint>,
) -> Rc<ConversionPlanJudgment> {
    {
        let named = Rc::new({
            let mut __result = Vec::new();
            for r in rows.iter().cloned() {
                if crate::std_decl_ref::declaration_ref_eq(r.route.clone(), route.clone()) {
                    __result.push(r);
                }
            }
            __result
        });
        let n = (named.clone().len() as i64);
        if (n.clone() == 0) {
            Rc::new(ConversionPlanJudgment::ConversionPlanAbsent {
                route: route.clone(),
            })
        } else {
            if (n.clone() > 1) {
                Rc::new(ConversionPlanJudgment::ConversionPlanAmbiguous {
                    route: route.clone(),
                    row_count: n.clone(),
                })
            } else {
                match named.clone().first().cloned() {
                    std::option::Option::None => {
                        Rc::new(ConversionPlanJudgment::ConversionPlanAbsent {
                            route: route.clone(),
                        })
                    }
                    Some(plan) => {
                        if (conversion_endpoint_eq(
                            conversion_plan_source(plan.clone()),
                            source.clone(),
                        ) && conversion_endpoint_eq(
                            conversion_plan_target(plan.clone()),
                            target.clone(),
                        )) {
                            Rc::new(ConversionPlanJudgment::ConversionPlanAdmitted {
                                plan: plan.clone(),
                            })
                        } else {
                            Rc::new(ConversionPlanJudgment::ConversionPlanEndpointMismatch {
                                plan: plan.clone(),
                            })
                        }
                    }
                }
            }
        }
    }
}

